type Account={id:string;name:string;kind:string;currency:string;balance:number|string;initial_balance?:number|string;icon_key?:string|null;sort_order?:number;created_at?:string;credit_limit?:number|string|null;payment_day?:number|null;linked_bank_account_id?:string|null}
type Tx={id:string;kind:'expense'|'income'|'transfer';amount:number|string;currency:string;account_id:string;transfer_to_account_id?:string|null;category_id?:string|null;note?:string;occurred_at:string;fee?:number|string;original_amount?:number|string|null;original_currency?:string|null;base_amount?:number|string|null;base_currency?:string|null;exchange_rate?:number|string|null;advance_enabled?:boolean;advance_person?:string|null;advance_amount?:number|string|null;advance_returned?:boolean;advance_return_account_id?:string|null}
type Todo={id:string;user_id?:string;title:string;due_at:string;location_name?:string;note?:string;remind_before_minutes?:number;is_done:boolean;category_id?:string|null;updated_at?:string;_sync?:'synced'|'pending'|'failed'}
type Journal={id:string;entry_date:string;mood:string;body:string;mood_category_id?:string|null}
type Category={id:string;scope:'transaction'|'todo'|'mood';name:string;icon?:string|null;sort_order:number;parent_id?:string|null;transaction_kind?:'expense'|'income'|null}
type BalanceAdjustment={id:string;account_id:string;amount:number|string;balance_before:number|string;balance_after:number|string;note:string;created_at:string}
type CreditCardRepayment={id:string;account_id:string;amount:number|string;occurred_at:string;created_at:string}
type SettingsRow={nickname:string;default_currency:string;quick_nav?:string[];feature_order?:string[];dashboard_order?:string[];password_vault_salt?:string|null;password_vault_verifier?:string|null;password_vault_key_cipher?:string|null;password_vault_key_iv?:string|null}
type RewardPoint={id:string;user_id:string;account_id:string;transaction_id?:string|null;points_name:string;plan_key:string;plan_name:string;reward_rate:number|string;purchase_amount:number|string;points:number|string;status:'pending'|'confirmed';note:string;occurred_at:string;created_at:string;updated_at:string}
