const LUCIDE_PICKER_ICONS=Object.entries(LucideIcons).filter(([name,Icon]:any)=>/^[A-Z]/.test(name)&&name!=='Icon'&&name!=='LucideIcon'&&(typeof Icon==='object'||typeof Icon==='function')).map(([name,Icon]:any)=>({name,Icon})).sort((a,b)=>a.name.localeCompare(b.name))
const categoryDisplayName=(value?:string|null)=>String(value||'').replace(/^lucide-dynamic:[A-Za-z0-9-]+\s*/,'').replace(/^lucide:[A-Za-z0-9-]+\s*/,'').trim()
function CategoryIcon({value,size=22}:any){const item=CATEGORY_ICON_OPTIONS.find(x=>x.key===value);if(item){const Icon=item.Icon;return <Icon size={size} strokeWidth={1.8}/>}if(String(value||'').startsWith('lucide-dynamic:')){const name=String(value).slice('lucide-dynamic:'.length);const match=LUCIDE_PICKER_ICONS.find(x=>x.name===name);if(match){const Icon:any=match.Icon;return <Icon size={size} strokeWidth={1.8}/>} }return <span className="category-custom-symbol">{value||'•'}</span>}
const money=(n:number,c='TWD')=>new Intl.NumberFormat('zh-TW',{style:'currency',currency:c,maximumFractionDigits:0}).format(n||0)
const advanceBaseAmount=(x:Tx)=>x.kind==='expense'&&x.advance_enabled?Math.max(0,Number(x.advance_amount||0)*(Number(x.base_amount??x.amount)/(Number(x.amount)||1))):0
const reportAmount=(x:Tx)=>Math.max(0,Number(x.base_amount??x.amount)-advanceBaseAmount(x))
const today=()=>new Date().toISOString().slice(0,10)
const previousWorkday=(date:string)=>{const d=new Date(date+'T12:00:00');do{d.setDate(d.getDate()-1)}while(d.getDay()===0||d.getDay()===6);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
