function AccountLogo({iconKey,name,size=42,kind}:any){const preset=ALL_ACCOUNT_PRESETS.find(x=>x.key===iconKey);return preset?<span className={'account-logo-frame '+(kind==='credit_card'||kind==='debit_card'?'credit-card-logo-frame':'')} style={{width:size,height:kind==='credit_card'||kind==='debit_card'?Math.round(size*1.42):size}}><img className="account-logo" src={preset.logo} alt={name||preset.name}/></span>:<span className="account-logo-frame account-logo-fallback" style={{width:size,height:size}}><Landmark size={Math.round(size*.52)}/></span>}

export default function App(){
  const[user,setUser]=useState<any>()
  const[view,setView]=useState('home')
  const[accounts,setAccounts]=useState<Account[]>([])
  const[txs,setTxs]=useState<Tx[]>([])
  const[todos,setTodos]=useState<Todo[]>([])
  const[journals,setJournals]=useState<Journal[]>([])
  const[categories,setCategories]=useState<Category[]>([])
  const[settings,setSettings]=useState<SettingsRow>({nickname:'',default_currency:'TWD',quick_nav:['home','accounts','ledger','todo'],feature_order:['home','accounts','ledger','todo','journal','travel','collections','pocket','health','books','passwords','settings']})
  const[adjustments,setAdjustments]=useState<BalanceAdjustment[]>([])
  const[repayments,setRepayments]=useState<CreditCardRepayment[]>([])
  const[msg,setMsg]=useState('')

  useEffect(()=>{supabase.auth.getSession().then(x=>setUser(x.data.session?.user));const{data}=supabase.auth.onAuthStateChange((_e,s)=>setUser(s?.user));return()=>data.subscription.unsubscribe()},[])
  const load=async()=>{
    if(!user)return
    const[a,t,d,j,c,s,ba,rp]=await Promise.all([
      supabase.from('accounts').select('*').order('sort_order').order('created_at'),
      supabase.from('transactions').select('*').order('occurred_at',{ascending:false}),
      supabase.from('todos').select('*').order('due_at'),
      supabase.from('journal_entries').select('*').order('entry_date',{ascending:false}),
      supabase.from('user_categories').select('*').order('sort_order'),
      supabase.from('user_settings').select('nickname,default_currency,quick_nav,feature_order,dashboard_order,password_vault_salt,password_vault_verifier,password_vault_key_cipher,password_vault_key_iv').eq('user_id',user.id).maybeSingle(),
      supabase.from('balance_adjustments').select('*').order('created_at',{ascending:false}),
      supabase.from('credit_card_repayments').select('*').order('occurred_at',{ascending:false}),
    ])
    setAccounts(a.data||[]);setTxs(t.data||[]);setTodos(d.data||[]);setJournals(j.data||[]);setCategories(c.data||[]);setAdjustments(ba.data||[]);setRepayments(rp.data||[])
    if(s.data)setSettings(s.data)
  }
  useEffect(()=>{if(!user)return;load();const channel=supabase.channel('wealthlife-sync').on('postgres_changes',{event:'*',schema:'public'},load).subscribe();return()=>{supabase.removeChannel(channel)}},[user])
  useEffect(()=>{if(!msg)return;const timer=window.setTimeout(()=>setMsg(''),5000);return()=>window.clearTimeout(timer)},[msg])
  if(!user)return <Auth/>

  const currentMonth=new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit'}).format(new Date())
  const transactionMonth=(value:string)=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Taipei',year:'numeric',month:'2-digit'}).format(new Date(value))
  const currentMonthTxs=txs.filter(x=>transactionMonth(x.occurred_at)===currentMonth)
  const income=currentMonthTxs.filter(x=>x.kind==='income').reduce((sum,x)=>sum+Number(x.base_amount??x.amount),0)
  const expense=currentMonthTxs.filter(x=>x.kind==='expense').reduce((sum,x)=>sum+reportAmount(x)+Number(x.fee||0),0)
  const net=accounts.filter(a=>a.kind!=='debit_card').reduce((s,a)=>s+(a.kind==='credit_card'?-1:a.kind==='liability'?-1:1)*Number(a.balance),0)
  const labels:any={home:'財務總覽',accounts:'帳戶',ledger:'記帳',todo:'待辦',journal:'日記',settings:'設定',travel:'旅遊',collections:'收藏文章',pocket:'口袋名單',health:'健康',books:'書籍',passwords:'密碼',more:'更多功能'}
  const featureDefs:any={home:[LayoutDashboard,'總覽'],accounts:[Landmark,'帳戶'],ledger:[WalletCards,'記帳'],todo:[CheckCircle2,'待辦'],journal:[BookOpen,'日記'],travel:[Plane,'旅遊'],collections:[Bookmark,'收藏'],pocket:[MapPin,'口袋名單'],health:[HeartPulse,'健康'],books:[BookOpen,'書籍'],passwords:[KeyRound,'密碼'],settings:[Settings,'設定']}
  const quickNav=(settings.quick_nav?.length?settings.quick_nav:['home','accounts','ledger','todo']).filter((id:string)=>featureDefs[id]).slice(0,4)
  const savedFeatureOrder=(settings.feature_order?.length?settings.feature_order:['home','accounts','ledger','todo','journal','travel','collections','pocket','health','books','passwords','settings']);const featureOrder=[...savedFeatureOrder,...Object.keys(featureDefs).filter(id=>!savedFeatureOrder.includes(id))].filter((id:string)=>featureDefs[id])
  const done=(m?:string,reload=true)=>{if(m)setMsg(m);if(reload)load()}

  return <div className="shell"><aside><div className="brand"><CircleDollarSign/>財日記</div>{quickNav.map((id:string)=>{const[Icon,label]=featureDefs[id];return <button className={view===id?'active':''} onClick={()=>setView(id)} key={id}><Icon size={19}/>{label}</button>})}<button className={view==='more'?'active':''} onClick={()=>setView('more')}><Menu size={19}/>更多</button><button className="logout" onClick={()=>supabase.auth.signOut()}><LogOut size={18}/>登出</button></aside><main><header><div><small>{settings.nickname?`${settings.nickname}・跨裝置同步`:'跨裝置同步'}</small><h1>{labels[view]}</h1></div><div className="header-actions"><span className="status">● 已連線</span></div></header>{msg&&<div className="toast">{msg}</div>}
    {view==='home'&&<Home user={user} net={net} income={income} expense={expense} accounts={accounts} txs={currentMonthTxs} categories={categories} defaultCurrency={settings.default_currency} dashboardOrder={settings.dashboard_order} done={done}/>} 
    {view==='accounts'&&<AccountsPage user={user} accounts={accounts} txs={txs} adjustments={adjustments} repayments={repayments} categories={categories} defaultCurrency={settings.default_currency} done={done}/>} 
    {view==='ledger'&&<Ledger user={user} accounts={accounts} txs={txs} repayments={repayments} categories={categories} defaultCurrency={settings.default_currency} done={done}/>} 
    {view==='todo'&&<Todos user={user} items={todos} categories={categories} done={done} onItemsChange={setTodos}/>} 
    {view==='travel'&&<TravelPage user={user} done={done}/>} 
    {view==='collections'&&<CollectionsPage user={user} done={done}/>} 
    {view==='pocket'&&<PocketListPage user={user} done={done}/>} 
    {view==='health'&&<HealthPage user={user} done={done}/>}   
    {view==='books'&&<BooksPage user={user} done={done}/>}  
    {view==='passwords'&&<PasswordVaultPage user={user} done={done}/>} 
    {view==='journal'&&<JournalPage user={user} items={journals} categories={categories} done={done}/>} 
    {view==='more'&&<MorePage quickNav={quickNav} featureOrder={featureOrder} featureDefs={featureDefs} onOpen={setView} user={user} done={done}/>} 
    {view==='settings'&&<SettingsPage user={user} settings={settings} categories={categories} accounts={accounts} txs={txs} done={done}/>} 
  </main></div>
}

function Auth(){const[email,setEmail]=useState(''),[password,setPassword]=useState(''),[info,setInfo]=useState('');async function submit(e:FormEvent,signup=false){e.preventDefault();const r=signup?await supabase.auth.signUp({email,password}):await supabase.auth.signInWithPassword({email,password});setInfo(r.error?.message||(signup?'註冊完成，請依設定驗證信箱':'登入成功'))}return <div className="auth"><form onSubmit={e=>submit(e)}><CircleDollarSign size={42}/><h1>財日記</h1><p>與 iPhone 共用同一個 Supabase 帳號</p><input type="email" placeholder="Email" value={email} onChange={e=>setEmail(e.target.value)} required/><input type="password" placeholder="密碼（至少 6 字元）" value={password} onChange={e=>setPassword(e.target.value)} required/><button>登入</button><button type="button" className="secondary" onClick={e=>submit(e as any,true)}>建立帳號</button><small>{info}</small></form></div>}
function Home({user,net,income,expense,accounts,txs,categories,defaultCurrency,dashboardOrder,done}:any){
  const[mode,setMode]=useState<'asset'|'debt'>('asset'),[cashflowMode,setCashflowMode]=useState<'expense'|'income'>('expense'),[selectedParent,setSelectedParent]=useState(''),[sorting,setSorting]=useState(false),[dragging,setDragging]=useState(''),[hideAmounts,setHideAmounts]=useState(false)
  const privateMoney=(value:number,currency=defaultCurrency)=>hideAmounts?money(value,currency).replace(/\d/g,'*'):money(value,currency)
  const defaultOrder=['net','summary','asset','cashflow'],labels:any={net:'我的淨資產',summary:'收支金額總覽',asset:'資產比例',cashflow:'收支比例圓餅圖'}
  const[order,setOrder]=useState<string[]>(dashboardOrder?.length?dashboardOrder:defaultOrder)
  useEffect(()=>setOrder(dashboardOrder?.length?dashboardOrder:defaultOrder),[JSON.stringify(dashboardOrder||[])])
  const assetKinds=['cash','bank','debit_card','transit_card','mobile_payment','gift_card'];const palette=['#7ee7a8','#ff9b73','#78a8ff','#e98cff','#f2d35f','#66d9dc','#ff6f91','#a3e635']
  const selected=accounts.filter((a:Account)=>mode==='asset'?assetKinds.includes(a.kind)&&Number(a.balance)>=0:(a.kind==='credit_card'||(a.kind!=='debit_card'&&Number(a.balance)<0))),total=selected.reduce((n:number,a:Account)=>n+Math.abs(Number(a.balance)),0),parts=selected.map((a:Account,i:number)=>({ ...a,chartValue:Math.abs(Number(a.balance)),percent:total?Math.abs(Number(a.balance))/total*100:0,color:palette[i%palette.length]}));let cursor=0;const pie=`conic-gradient(${parts.map((a:any)=>{const from=cursor;cursor+=a.percent;return `${a.color} ${from}% ${cursor}%`}).join(',')})`
  const txAmount=(x:Tx)=>x.kind==='expense'?reportAmount(x):Number(x.base_amount??x.amount)
  const expenseParents=categories.filter((c:Category)=>c.scope==='transaction'&&c.transaction_kind==='expense'&&!c.parent_id)
  const expenseParts=expenseParents.map((parent:Category,i:number)=>{const children=categories.filter((c:Category)=>c.parent_id===parent.id),ids=new Set([parent.id,...children.map((c:Category)=>c.id)]),value=txs.filter((x:Tx)=>x.kind==='expense'&&x.category_id&&ids.has(x.category_id)).reduce((n:number,x:Tx)=>n+txAmount(x),0);return{id:parent.id,name:parent.name,value,color:palette[i%palette.length],children}}).filter((x:any)=>x.value>0)
  const incomeCats=categories.filter((c:Category)=>c.scope==='transaction'&&c.transaction_kind==='income');const incomeParts=incomeCats.map((c:Category,i:number)=>({id:c.id,name:c.name,value:txs.filter((x:Tx)=>x.kind==='income'&&x.category_id===c.id).reduce((n:number,x:Tx)=>n+txAmount(x),0),color:palette[i%palette.length],children:[]})).filter((x:any)=>x.value>0)
  const flowParts=cashflowMode==='expense'?expenseParts:incomeParts,flowTotal=flowParts.reduce((n:number,x:any)=>n+x.value,0);let flowCursor=0;const flowPie=flowParts.length?`conic-gradient(${flowParts.map((x:any)=>{const from=flowCursor;flowCursor+=flowTotal?x.value/flowTotal*100:0;return `${x.color} ${from}% ${flowCursor}%`}).join(',')})`:'#222';const activeParent=expenseParts.find((x:any)=>x.id===selectedParent)
  function drop(target:string){if(!dragging||dragging===target)return;const next=[...order],from=next.indexOf(dragging),to=next.indexOf(target);next.splice(to,0,next.splice(from,1)[0]);setOrder(next);setDragging('')}
  async function saveOrder(){const{error}=await supabase.rpc('update_dashboard_order',{p_dashboard_order:order});if(error)return done(`排序儲存失敗：${error.message}`,false);setSorting(false);done('總覽順序已更新')}
  const sections:any={
    net:<section className="hero"><span>我的淨資產</span><strong>{privateMoney(net)}</strong></section>,
    summary:<div className="cards"><Card t="本月收入" v={privateMoney(income)} c="green"/><Card t="本月支出" v={privateMoney(expense)} c="orange"/><Card t="資產" v={privateMoney(accounts.filter((a:Account)=>assetKinds.includes(a.kind)&&Number(a.balance)>=0).reduce((n:number,a:Account)=>n+Number(a.balance),0))} c="blue"/><Card t="負債" v={privateMoney(accounts.filter((a:Account)=>a.kind==='credit_card'||(a.kind!=='debit_card'&&Number(a.balance)<0)).reduce((n:number,a:Account)=>n+Math.abs(Number(a.balance)),0))} c="pink"/></div>,
    asset:<section className="panel asset-panel"><div className="asset-title"><h2>{mode==='asset'?'資產比例':'負債比例'}</h2><div className="asset-switch"><button className={mode==='asset'?'on':''} onClick={()=>setMode('asset')}>資產</button><button className={mode==='debt'?'on':''} onClick={()=>setMode('debt')}>負債</button></div></div>{parts.length?<div className="asset-chart-layout"><div className="asset-pie" style={{background:pie}}><div><b>{privateMoney(total)}</b><small>{mode==='asset'?'資產總額':'負債總額'}</small></div></div><div className="asset-legend">{parts.map((a:any)=><div className="asset-legend-row" key={a.id}><i style={{background:a.color}}/><span>{a.name}<small>{a.currency}</small></span><b>{a.percent.toFixed(1)}%<small>{privateMoney(a.chartValue,a.currency)}</small></b></div>)}</div></div>:<p className="empty">尚無可顯示的{mode==='asset'?'資產':'負債'}帳戶</p>}</section>,
    cashflow:<section className="panel cashflow-panel"><div className="asset-title"><h2>{cashflowMode==='expense'?'本月支出比例':'本月收入比例'}</h2><div className="asset-switch"><button className={cashflowMode==='expense'?'on':''} onClick={()=>{setCashflowMode('expense');setSelectedParent('')}}>支出</button><button className={cashflowMode==='income'?'on':''} onClick={()=>{setCashflowMode('income');setSelectedParent('')}}>收入</button></div></div>{flowParts.length?<><div className="asset-chart-layout"><div className="asset-pie cashflow-pie" style={{background:flowPie}}><div><b>{privateMoney(flowTotal,defaultCurrency)}</b><small>{cashflowMode==='expense'?'本月支出':'本月收入'}</small></div></div><div className="asset-legend">{flowParts.map((x:any)=><button className={'asset-legend-row cashflow-legend-row '+(selectedParent===x.id?'on':'')} onClick={()=>cashflowMode==='expense'&&setSelectedParent(selectedParent===x.id?'':x.id)} key={x.id}><i style={{background:x.color}}/><span>{x.name}</span><b>{(x.value/flowTotal*100).toFixed(1)}%<small>{privateMoney(x.value,defaultCurrency)}</small></b></button>)}</div></div>{cashflowMode==='expense'&&activeParent&&<div className="subcategory-breakdown"><h3>{activeParent.name} 子分類</h3>{activeParent.children.map((child:Category)=>{const value=txs.filter((x:Tx)=>x.kind==='expense'&&x.category_id===child.id).reduce((n:number,x:Tx)=>n+txAmount(x),0);return value>0?<div key={child.id}><span>{categoryDisplayName(child.name)}</span><b>{privateMoney(value,defaultCurrency)}<small>占所有支出 {(value/flowTotal*100).toFixed(1)}%・占此母分類 {(value/activeParent.value*100).toFixed(1)}%</small></b></div>:null})}</div>}</>:<p className="empty">本月尚無{cashflowMode==='expense'?'支出':'收入'}資料</p>}</section>
  }
  return <><div className="dashboard-tools"><button type="button" className="privacy-toggle" title={hideAmounts?'顯示金額':'隱藏金額'} aria-label={hideAmounts?'顯示金額':'隱藏金額'} onClick={()=>setHideAmounts(v=>!v)}>{hideAmounts?<Eye size={20}/>:<EyeOff size={20}/>}</button><button title="排序總覽" aria-label="排序總覽" onClick={()=>setSorting(true)}><Menu size={20}/></button></div><div className="dashboard-sections">{order.map(id=><div key={id}>{sections[id]}</div>)}</div>{sorting&&<div className="modal"><div className="panel dashboard-sort-modal"><button className="modal-close" onClick={()=>setSorting(false)}><X/></button><h2>總覽排序</h2><div className="dashboard-sort-list">{order.map(id=><div draggable onDragStart={()=>setDragging(id)} onDragOver={e=>e.preventDefault()} onDrop={()=>drop(id)} key={id}><GripVertical size={18}/><span>{labels[id]}</span></div>)}</div><button onClick={saveOrder}>確認</button></div></div>}</>
}
function Card(p:any){return <section className={'card '+p.c}><span>{p.t}</span><b>{p.v}</b></section>}

