function iso(v:any){const noon=(y:number,m:number,d:number)=>new Date(y,m-1,d,12,0,0).toISOString();if(v instanceof Date)return noon(v.getFullYear(),v.getMonth()+1,v.getDate());if(typeof v==='number'){const d=XLSX.SSF.parse_date_code(v);return noon(d.y,d.m,d.d)}const text=String(v??'').trim();const matched=text.match(/^(\d{4})[\/-](\d{1,2})[\/-](\d{1,2})/);if(matched)return noon(Number(matched[1]),Number(matched[2]),Number(matched[3]));const d=new Date(text);return isNaN(d.getTime())?'':noon(d.getFullYear(),d.getMonth()+1,d.getDate())}
